template.schema:
type ProductCategory = "storage" | "compute" | "database" | "networking";

type Pricing = {
  model: "perHour" | "perMonth" | "perRequest";
  basePrice: number;
  /** Price per additional unit beyond the base tier, if applicable. */
  overage?: number;
};

type Benchmark = {
  name: string;
  score: number;
  unit: string;
};

type Provider = {
  name: string;
  region: string;
  category: ProductCategory;
  pricing: Pricing;
  benchmarks: Benchmark[];
  pros: string[];
  cons: string[];
};

interface Input {
  providers: Provider[];
  /** The use case this comparison should be framed around. */
  useCase: string;
  /** Target audience for the article. */
  audience: "developer" | "architect" | "businessDecisionMaker";
}

interface Output {
  title: string;
  introduction: string;
  /** One section per provider. */
  sections: {
    providerName: string;
    body: string;
  }[];
  conclusion: string;
  recommendation: string;
}
